CREATE OR REPLACE FUNCTION authz_int."ticket__col_audit_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    -- the rows whose key changed, or a column access may read: a relation's, or one a condition names (a
    -- column no rule reads changes no access, and isn't announced)
    PERFORM authz_int.changed('ticket', ARRAY(
        SELECT n."id"::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text)
        UNION SELECT o."id"::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id"::text = o."id"::text)
        UNION SELECT n."id"::text FROM new_rows n JOIN old_rows o ON n."id"::text = o."id"::text
        WHERE n."assignee_id" IS DISTINCT FROM o."assignee_id" OR n."requester_id" IS DISTINCT FROM o."requester_id" OR n."team_id" IS DISTINCT FROM o."team_id" OR n."workspace_id" IS DISTINCT FROM o."workspace_id" OR (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(n.*)) e WHERE lower(e.key) = ANY (ARRAY['and', 'in', 'is', 'null', 'status'])) IS DISTINCT FROM (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(o.*)) e WHERE lower(e.key) = ANY (ARRAY['and', 'in', 'is', 'null', 'status']))), 'update');
    -- a partitioned table: the rows this update put in another partition, which the row trigger never sees
    IF (SELECT relkind FROM pg_class WHERE oid = TG_RELID) = 'p' THEN
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'ticket', n."id"::text, 'workspace', n."workspace_id"::text, jsonb_build_object('column', 'workspace_id', 'was', o."workspace_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."workspace_id" IS DISTINCT FROM o."workspace_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'ticket'
          AND a.object_id = n."id"::text AND a.relation = 'workspace' AND a.detail->>'column' = 'workspace_id'
          AND a.subject_id IS NOT DISTINCT FROM n."workspace_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."workspace_id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'ticket', n."id"::text, 'requester', n."requester_id"::text, jsonb_build_object('column', 'requester_id', 'was', o."requester_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."requester_id" IS DISTINCT FROM o."requester_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'ticket'
          AND a.object_id = n."id"::text AND a.relation = 'requester' AND a.detail->>'column' = 'requester_id'
          AND a.subject_id IS NOT DISTINCT FROM n."requester_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."requester_id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'ticket', n."id"::text, 'team', n."team_id"::text, jsonb_build_object('column', 'team_id', 'was', o."team_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."team_id" IS DISTINCT FROM o."team_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'ticket'
          AND a.object_id = n."id"::text AND a.relation = 'team' AND a.detail->>'column' = 'team_id'
          AND a.subject_id IS NOT DISTINCT FROM n."team_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."team_id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'ticket', n."id"::text, 'assignee', n."assignee_id"::text, jsonb_build_object('column', 'assignee_id', 'was', o."assignee_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."assignee_id" IS DISTINCT FROM o."assignee_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'ticket'
          AND a.object_id = n."id"::text AND a.relation = 'assignee' AND a.detail->>'column' = 'assignee_id'
          AND a.subject_id IS NOT DISTINCT FROM n."assignee_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."assignee_id"));
    END IF;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."comment__col_audit_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    -- the rows whose key changed, or a column access may read: a relation's, or one a condition names (a
    -- column no rule reads changes no access, and isn't announced)
    PERFORM authz_int.changed('comment', ARRAY(
        SELECT n."id"::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text)
        UNION SELECT o."id"::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id"::text = o."id"::text)
        UNION SELECT n."id"::text FROM new_rows n JOIN old_rows o ON n."id"::text = o."id"::text
        WHERE n."author_id" IS DISTINCT FROM o."author_id" OR n."integration_id" IS DISTINCT FROM o."integration_id" OR n."ticket_id" IS DISTINCT FROM o."ticket_id" OR (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(n.*)) e WHERE lower(e.key) = ANY (ARRAY['internal', 'not'])) IS DISTINCT FROM (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(o.*)) e WHERE lower(e.key) = ANY (ARRAY['internal', 'not']))), 'update');
    -- a partitioned table: the rows this update put in another partition, which the row trigger never sees
    IF (SELECT relkind FROM pg_class WHERE oid = TG_RELID) = 'p' THEN
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'comment', n."id"::text, 'ticket', n."ticket_id"::text, jsonb_build_object('column', 'ticket_id', 'was', o."ticket_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."ticket_id" IS DISTINCT FROM o."ticket_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'comment'
          AND a.object_id = n."id"::text AND a.relation = 'ticket' AND a.detail->>'column' = 'ticket_id'
          AND a.subject_id IS NOT DISTINCT FROM n."ticket_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."ticket_id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'comment', n."id"::text, 'author', n."author_id"::text, jsonb_build_object('column', 'author_id', 'was', o."author_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."author_id" IS DISTINCT FROM o."author_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'comment'
          AND a.object_id = n."id"::text AND a.relation = 'author' AND a.detail->>'column' = 'author_id'
          AND a.subject_id IS NOT DISTINCT FROM n."author_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."author_id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'comment', n."id"::text, 'via', n."integration_id"::text, jsonb_build_object('column', 'integration_id', 'was', o."integration_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."integration_id" IS DISTINCT FROM o."integration_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'comment'
          AND a.object_id = n."id"::text AND a.relation = 'via' AND a.detail->>'column' = 'integration_id'
          AND a.subject_id IS NOT DISTINCT FROM n."integration_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."integration_id"));
    END IF;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."workspace__col_audit_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    -- the rows whose key changed, or a column access may read: a relation's, or one a condition names (a
    -- column no rule reads changes no access, and isn't announced)
    PERFORM authz_int.changed('workspace', ARRAY(
        SELECT n."id"::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text)
        UNION SELECT o."id"::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id"::text = o."id"::text)
        UNION SELECT n."id"::text FROM new_rows n JOIN old_rows o ON n."id"::text = o."id"::text
        WHERE (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(n.*)) e WHERE lower(e.key) = ANY (ARRAY['open_queue'])) IS DISTINCT FROM (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(o.*)) e WHERE lower(e.key) = ANY (ARRAY['open_queue']))), 'update');
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."hd.users:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE r_old "hd"."users"; r_new "hd"."users";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY(SELECT * FROM authz_gen."hd.users:insert:why"(jsonb_populate_record(NULL::"hd"."users", coalesce(p_row, '{}'))));
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'hd.users', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  SELECT (jsonb_populate_record(NULL::"hd"."users", to_jsonb(x.*))).* INTO r_old FROM "hd"."users_visible" x WHERE x."id" = p_id::uuid;
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY['no   there is no delete rule for hd.users: nobody may delete its rows'];
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY(SELECT * FROM authz_gen."hd.users:update:why"(r_old, true)) || CASE WHEN p_row IS NULL THEN '{}'::text[] ELSE ARRAY['after the change:'] || ARRAY(SELECT '  ' || l FROM authz_gen."hd.users:update:why"(r_new, false) l) END;
END $f$;

