             AND a.attnum > 0 AND NOT a.attisdropped AND a.attgenerated <> '') THEN
    EXECUTE 'CREATE TRIGGER "authz_update_after parent_id" AFTER UPDATE ON "hd"."teams" FOR EACH ROW
  WHEN ((OLD."parent_id" IS DISTINCT FROM NEW."parent_id")
    AND pg_catalog.row_security_active(''"hd"."teams"''::pg_catalog.regclass)
