REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

DO $gf$
DECLARE f regprocedure;
BEGIN
  FOR f IN SELECT p.oid::regprocedure FROM pg_proc p WHERE p.pronamespace = 'authz_gen'::regnamespace
           AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"hd.comments:delete:items"', '"hd.comments:delete:why"', '"hd.comments:insert:items"', '"hd.comments:insert:refuse"', '"hd.comments:insert:why"', '"hd.comments:rules:explain"', '"hd.comments:update:items"', '"hd.comments:update:refuse"', '"hd.comments:update:why"', '"hd.customer_orgs:column id, workspace_id:items"', '"hd.customer_orgs:column id, workspace_id:why"', '"hd.customer_orgs:delete:items"', '"hd.customer_orgs:delete:why"', '"hd.customer_orgs:insert:items"', '"hd.customer_orgs:insert:refuse"', '"hd.customer_orgs:insert:why"', '"hd.customer_orgs:rules:explain"', '"hd.customer_orgs:update:items"', '"hd.customer_orgs:update:refuse"', '"hd.customer_orgs:update:why"', '"hd.integrations:column id, workspace_id:items"', '"hd.integrations:column id, workspace_id:why"', '"hd.integrations:delete:items"', '"hd.integrations:delete:why"', '"hd.integrations:insert:items"', '"hd.integrations:insert:refuse"', '"hd.integrations:insert:why"', '"hd.integrations:rules:explain"', '"hd.integrations:update:items"', '"hd.integrations:update:refuse"', '"hd.integrations:update:why"', '"hd.support_access:delete:items"', '"hd.support_access:delete:why"', '"hd.support_access:insert:items"', '"hd.support_access:insert:refuse"', '"hd.support_access:insert:why"', '"hd.support_access:rules:explain"', '"hd.support_access:update:items"', '"hd.support_access:update:refuse"', '"hd.support_access:update:why"', '"hd.team_leads:delete:items"', '"hd.team_leads:delete:why"', '"hd.team_leads:insert:items"', '"hd.team_leads:insert:refuse"', '"hd.team_leads:insert:why"', '"hd.team_leads:rules:explain"', '"hd.team_leads:update:items"', '"hd.team_leads:update:refuse"', '"hd.team_leads:update:why"', '"hd.team_members:delete:items"', '"hd.team_members:delete:why"', '"hd.team_members:insert:items"', '"hd.team_members:insert:refuse"', '"hd.team_members:insert:why"', '"hd.team_members:rules:explain"', '"hd.team_members:update:items"', '"hd.team_members:update:refuse"', '"hd.team_members:update:why"', '"hd.teams:column id, workspace_id:items"', '"hd.teams:column id, workspace_id:why"', '"hd.teams:column parent_id after:items"', '"hd.teams:column parent_id after:why"', '"hd.teams:delete:items"', '"hd.teams:delete:why"', '"hd.teams:insert:items"', '"hd.teams:insert:refuse"', '"hd.teams:insert:why"', '"hd.teams:rules:explain"', '"hd.teams:update:items"', '"hd.teams:update:refuse"', '"hd.teams:update:why"', '"hd.tickets:column created_at:items"', '"hd.tickets:column created_at:why"', '"hd.tickets:column id, workspace_id, requester_id:items"', '"hd.tickets:column id, workspace_id, requester_id:why"', '"hd.tickets:column status after:items"', '"hd.tickets:column status after:why"', '"hd.tickets:column status:items"', '"hd.tickets:column status:why"', '"hd.tickets:column team_id, assignee_id:items"', '"hd.tickets:column team_id, assignee_id:why"', '"hd.tickets:delete:items"', '"hd.tickets:delete:why"', '"hd.tickets:insert:items"', '"hd.tickets:insert:refuse"', '"hd.tickets:insert:why"', '"hd.tickets:rules:explain"', '"hd.tickets:update:items"', '"hd.tickets:update:refuse"', '"hd.tickets:update:why"', '"hd.tickets:update_after:items"', '"hd.tickets:update_after:refuse"', '"hd.tickets:update_after:why"', '"hd.users:column customer_org_id:items"', '"hd.users:column customer_org_id:why"', '"hd.users:column email:items"', '"hd.users:column email:why"', '"hd.users:column id, workspace_id, kind:items"', '"hd.users:column id, workspace_id, kind:why"', '"hd.users:column name:items"', '"hd.users:column name:why"', '"hd.users:column notes:items"', '"hd.users:column notes:why"', '"hd.users:column role, active:items"', '"hd.users:column role, active:why"', '"hd.users:insert:items"', '"hd.users:insert:refuse"', '"hd.users:insert:why"', '"hd.users:rules:explain"', '"hd.users:update:items"', '"hd.users:update:refuse"', '"hd.users:update:why"', '"hd.workspaces:column id:items"', '"hd.workspaces:column id:why"', '"hd.worksp